CREATE VIEW [dbo].[StoricoApparecchi] AS SELECT * FROM ( SELECT 'New Slot' AS Tipo, storico.codicelocale AS IdLocale,2 AS TipoOggetto,'NSL' AS TipoOggettoDesc,storico.CodiceOggetto,dedicati.prop AS Proprieta,dedicati.agente AS Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, storico.idstorico, 0 AS Ordinamento, storico.ndatainizio as DataDa, storico.ndatafine as DataA FROM storico,dedicati WHERE dedicati.iddedicato=storico.codiceoggetto AND dedicati.partipologiamonopoli=1 AND storico.tipo=2 Union SELECT 'Gioco' AS Tipo, storico.codicelocale AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,storico.CodiceOggetto,dedicati.prop AS Proprieta,dedicati.agente AS Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, storico.idstorico,1 AS Ordinamento , storico.ndatainizio as DataDa, storico.ndatafine as DataA FROM storico,dedicati WHERE dedicati.iddedicato=storico.codiceoggetto AND (dedicati.partipologiamonopoli<>1 OR dedicati.partipologiamonopoli IS NULL)  AND storico.tipo=2 Union SELECT 'Mobile' AS Tipo, storico.codicelocale AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,storico.CodiceOggetto,mobili.prop AS Proprieta,mobili.agente AS Associato, mobili.matricola,mobili.modello as Modello, mobili.identificativo,mobili.nullaosta, storico.idstorico,2 AS Ordinamento , storico.ndatainizio as DataDa, storico.ndatafine as DataA FROM storico,mobili WHERE mobili.idmobile=storico.codiceoggetto  AND storico.tipo=0 Union SELECT 'Scheda' AS Tipo, storico.codicelocale,1 AS TipoOggetto,'SCH' AS TipoOggettoDesc, storico.CodiceOggetto,schede.prop AS Proprieta,schede.agente AS Associato, schede.matricola,schede.nome as Modello, '' AS identificativo,'' AS nullaosta, storico.idstorico,3 AS Ordinamento , storico.ndatainizio as DataDa, storico.ndatafine as DataA FROM storico ,schede WHERE schede.idscheda=storico.codiceoggetto AND  storico.tipo=1 Union SELECT 'Distributore' AS Tipo, storico.codicelocale AS IdLocale,15 AS TipoOggetto,'DIS' AS TipoOggettoDesc, storico.CodiceOggetto,distribut.prop AS Proprieta,distribut.agente AS Associato, distribut.matricola,distribut.nome as Modello, '' AS identificativo,'' AS nullaosta, storico.idstorico,4 AS Ordinamento , storico.ndatainizio as DataDa, storico.ndatafine as DataA FROM storico,distribut WHERE distribut.iddistributore=storico.codiceoggetto AND  storico.tipo=15 Union SELECT 'Accessorio' AS Tipo, storico.codicelocale AS IdLocale,3 AS TipoOggetto,'ACC' AS TipoOggettoDesc, storico.CodiceOggetto,Accessori.prop AS Proprieta,'' AS Associato, Accessori.matricola,Accessori.nome as Modello, '' AS identificativo,'' AS nullaosta, storico.idstorico ,5 AS Ordinamento , storico.ndatainizio as DataDa, storico.ndatafine as DataA FROM storico,Accessori WHERE Accessori.IdAccessorio=storico.codiceoggetto  AND storico.tipo=3 ) AS STORMAC
GO
